":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"offerId","type":"uint256"}],"name":"offerInfo","outputs":[{"components":[{"internalType":"uint256","name":"listingId","type":"uint256"},{"internalType":"address","name":"buyer","type":"address"},{"internalType":"enum FleaMarket.OfferStatus","name":"status","type":"uint8"},{"internalType":"euint64","name":"amount","type":"bytes32"}],"internalType":"struct FleaMarket.Offer","name":"","type":"tuple"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"owner","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"purchaseCount","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"purchaseId","type":"uint256"}],"name":"purchaseInfo","outputs":[{"components":[{"internalType":"uint256","name":"listingId","type":"uint256"},{"internalType":"address","name":"buyer","type":"address"},{"internalType":"enum FleaMarket.PurchaseStatus","name":"status","type":"uint8"},{"internalType":"uint64","name":"price","type":"uint64"},{"internalType":"euint64","name":"paid","type":"bytes32"},{"internalType":"ebool","name":"ok","type":"bytes32"}],"internalType":"struct FleaMarket.Purchase","name":"","type":"tuple"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"rats","outputs":[{"internalType":"contract IERC721","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"renounceOwnership","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"listingId","type":"uint256"},{"internalType":"uint64","name":"price","type":"uint64"}],"name":"reprice","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint16","name":"feeBps_","type":"uint16"}],"name":"setFee","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"treasury_","type":"address"}],"name":"setTreasury","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"newOwner","type":"address"}],"name":"transferOwnership","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"treasury","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"offerId","type":"uint256"}],"name":"withdrawOffer","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"details":"Design notes.  1. The market holds what it sells. A rat (plain ERC-721) is escrowed with `transferFrom` and     listed at once. A box is a confidential ERC-721: nobody can check its owner, so `list`     pulls it with `confidentialTransferFrom`, which never reverts, and makes the "it arrived"     bit publicly decryptable; `finalizeListing` proves it. Only a seller who held the box gets     an active listing, and since the market then holds it, nobody else can list it again.  2. Payments are all-or-nothing cUSDC pulls (ERC-7984): what arrived is either the amount or     zero, encrypted. A purchase stores what arrived and refunds it unless the sale settles,     so a buyer who could not pay, or who was beaten to the item, gets back exactly what left     their wallet. Several purchases may be pending on one listing: the first one settled     with "paid" wins, the others are refunded. Nothing locks a listing.  3. A secret offer is capped at `MAX_PRICE` under encryption, so the fee computed on it can     never overflow. The seller decrypts the amount before accepting; an offer from an empty     wallet holds zero and the seller sees it.  4. A box is sold in a given public state (sealed or opened, entangled or not, vet checked or     not). The collection's hooks take a snapshot of it at listing; if it changed (an     entangled partner opened it, say), buying and accepting revert, and a pending purchase is     refunded.  5. What becomes public: the seller of a listing (once active), the asking price, the buyer of     a sale, and per purchase whether the buyer could pay. Never public: balances, offer     amounts, the price of a sale made by offer, or what is inside a sealed box.","errors":{"OwnableInvalidOwner(address)":[{"details":"The owner is not a valid owner account. (eg. `address(0)`)"}],"OwnableUnauthorizedAccount(address)":[{"details":"The caller account is not authorized to perform an operation."}],"ReentrancyGuardReentrantCall()":[{"details":"Unauthorized reentrant call."}]},"kind":"dev","methods":{"owner()":{"details":"Returns the address of the current owner."},"renounceOwnership()":{"details":"Leaves the contract without owner. It will not be possible to call `onlyOwner` functions. Can only be called by the current owner. NOTE: Renouncing ownership will leave the contract without an owner, thereby disabling any functionality that is only available to the owner."},"transferOwnership(address)":{"details":"Transfers ownership of the contract to a new account (`newOwner`). Can only be called by the current owner."}},"title":"The flea market","version":1},"userdoc":{"errors":{"InvalidKMSSignatures()":[{"notice":"Returned if the returned KMS signatures are not valid."}],"SenderNotAllowedToUseHandle(bytes32,address)":[{"notice":"Returned if the sender is not allowed to use the handle."}],"ZamaProtocolUnsupported()":[{"notice":"Returned if the Zama protocol is not supported on the current chain"}]},"events":{"ListingSettled(uint256,bool)":{"notice":"The box arrived (`active`) or did not, and the listing was refused."},"OfferMade(uint256,uint256,address)":{"notice":"The amount is deliberately absent: only the buyer and the seller can read it."},"PublicDecryptionVerified(bytes32[],bytes)":{"notice":"This event is emitted when public decryption has been successfully verified."},"Sold(uint256,address,address,uint64,bool)":{"notice":"An item changed hands. `price` is zero for a sale made by secret offer."}},"kind":"user","methods":{"MAX_FEE_BPS()":{"notice":"The fee can never exceed 10%."},"MAX_PRICE()":{"notice":"One million USDC: the most an item can be listed or offered for."},"acceptOffer(uint256)":{"notice":"The seller sells to `offerId` for its escrowed amount, which stays secret. The         seller should decrypt it first: the contract cannot tell them it is worth it."},"boxHooks()":{"notice":"Checks a box's public state between listing and sale. May be zero."},"buy(uint256)":{"notice":"Step 1 of a purchase at the asking price. Pulls the price in cUSDC (the market         must be the caller's cUSDC operator) and makes "paid" publicly decryptable."},"cancelListing(uint256)":{"notice":"Takes the item back. Open offers stay withdrawable by their buyers."},"finalizeListing(uint256,bytes,bytes)":{"notice":"Step 2 of a box listing. Anyone may submit the decrypted "arrived" bit with its         KMS proof (the relayer's `publicDecrypt` of `listingInfo(listingId).arrived`)."},"finalizePurchase(uint256,bytes,bytes)":{"notice":"Step 2 of a purchase. Anyone may submit the decrypted "paid" bit with its KMS         proof. Delivers the item if the buyer paid and the listing is still as bought;         refunds whatever arrived otherwise."},"list(uint8,uint256,uint64)":{"notice":"Puts `tokenId` up for `price` cUSDC (6 decimals). The market must be the caller's         operator on the boxes (`setOperator`) or approved on the rats. A rat is listed at         once; a box waits for `finalizeListing`."},"listings(uint256,uint256)":{"notice":"Up to `count` listings from `from`, for pages that read the chain directly."},"makeOffer(uint256,bytes32,bytes)":{"notice":"Escrows a secret offer on an active listing: `amount` is encrypted by the caller         for this contract, capped at `MAX_PRICE`. Only the caller and the seller can read         what was escrowed (zero if the caller held less)."},"reprice(uint256,uint64)":{"notice":"Changes the asking price. Pending purchases at the old price are refunded."},"withdrawOffer(uint256)":{"notice":"The buyer takes their offer back, whatever became of the listing."}},"notice":"Where players sell each other boxes, cats (opened boxes) and rats, in cUSDC.         Two ways to buy:         - at the asking price, which is public: `buy`, then a public decryption of "the buyer           paid it" settles the sale (`finalizePurchase`);         - with a secret offer: `makeOffer` escrows an encrypted amount that only the seller           and the buyer can read; `acceptOffer` sells at once. That price is never public.","version":1}},"settings":{"compilationTarget":{"contracts/FleaMarket.sol":"FleaMarket"},"evmVersion":"cancun","libraries":{},"metadata":{"bytecodeHash":"none","useLiteralContent":true},"optimizer":{"enabled":true,"runs":200},"remappings":[]},"sources":{"@fhevm/solidity/config/ZamaConfig.sol":{"content":"// SPDX-License-Identifier: BSD-3-Clause-Clear
pragma solidity ^0.8.24;

import {FHE} from "@fhevm/solidity/lib/FHE.sol";
import {CoprocessorConfig} from "@fhevm/solidity/lib/Impl.sol";

/**
 * @title   ZamaConfig.
 * @notice  This library returns the FHEVM config for different networks
 *          with the contract addresses for (1) ACL, (2) CoprocessorAddress, (3) KMSVerifier,
 *          which are deployed & maintained by Zama.
 */
library ZamaConfig {
    /// @notice Returned if the Zama protocol is not supported on the current chain
    error ZamaProtocolUnsupported();

    function getEthereumCoprocessorConfig() internal view returns (CoprocessorConfig memory config) {
        if (block.chainid == 1) {
            config = _getEthereumConfig();
        } else if (block.chainid == 11155111) {
            config = _getSepoliaConfig();
        } else if (block.chainid == 31337) {
            config = _getLocalConfig();
        } else {
            revert ZamaProtocolUnsupported();
        }
    }

    function getConfidentialProtocolId() internal view returns (uint256) {
        if (block.chainid == 1) {
            return _getEthereumProtocolId();
        } else if (block.chainid == 11155111) {
            return _getSepoliaProtocolId();
        } else if (block.chainid == 31337) {
            return _getLocalProtocolId();
        }
        return 0;
    }

    /// @dev chainid == 1
    function _getEthereumProtocolId() private pure returns (uint256) {
        // Zama Ethereum protocol id is '1'
        return 1;
    }

    /// @dev chainid == 1
    function _getEthereumConfig() private pure returns (CoprocessorConfig memory) {
        // The addresses below are placeholders and should be replaced with actual addresses
        // once deployed on the Ethereum mainnet.
        return
            CoprocessorConfig({
                ACLAddress: 0xcA2E8f1F656CD25C01F05d0b243Ab1ecd4a8ffb6,
                CoprocessorAddress: 0xD82385dADa1ae3E969447f20A3164F6213100e75,
                KMSVerifierAddress: 0x77627828a55156b04Ac0DC0eb30467f1a552BB03
            });
    }

    /// @dev chainid == 11155111
    function _getSepoliaProtocolId() private pure returns (uint256) {
        // Zama Ethereum Sepolia protocol id is '10000 + Zama Ethereum protocol id'
        return 10001;
    }

    /// @dev chainid == 11155111
    function _getSepoliaConfig() private pure returns (CoprocessorConfig memory) {
        return
            CoprocessorConfig({
                ACLAddress: 0xf0Ffdc93b7E186bC2f8CB3dAA75D86d1930A433D,
                CoprocessorAddress: 0x92C920834Ec8941d2C77D188936E1f7A6f49c127,
                KMSVerifierAddress: 0xbE0E383937d564D7FF0BC3b46c51f0bF8d5C311A
            });
    }

    /// @dev chainid == 31337
    function _getLocalProtocolId() private pure returns (uint256) {
        return type(uint256).max;
    }

    function _getLocalConfig() private pure returns (CoprocessorConfig memory) {
        return
            CoprocessorConfig({
                ACLAddress: 0x50157CFfD6bBFA2DECe204a89ec419c23ef5755D,
                CoprocessorAddress: 0xe3a9105a3a932253A70F126eb1E3b589C643dD24,
                KMSVerifierAddress: 0x901F8942346f7AB3a01F6D7613119Bca447Bb030
            });
    }
}

/**
 * @title   ZamaEthereumConfig.
 * @dev     This contract can be inherited by a contract wishing to use the FHEVM contracts provided by Zama
 *          on the Ethereum (mainnet) network (chainId = 1) or Sepolia (testnet) network (chainId = 11155111).
 *          Other providers may offer similar contracts deployed at different addresses.
 *          If you wish to use them, you should rely on the instructions from these providers.
 */
abstract contract ZamaEthereumConfig {
    constructor() {
        FHE.setCoprocessor(ZamaConfig.getEthereumCoprocessorConfig());
    }

    function confidentialProtocolId() public view returns (uint256) {
        return ZamaConfig.getConfidentialProtocolId();
    }
}
